// Generated by Claude (Opus 5.5), 2026-10-25
// spsc-stress-test.cpp
// Two-thread stress test for RingBuffer (spsc.hpp), meant to run under ThreadSanitizer.
// One producer pushes seq = 0..N-1, one consumer checks every item arrives once, in order,
// and intact. TSan reports any data race; halt_on_error makes the run fail on the first one.
//
// Build (from src/feed-handler/claude):
//   g++-14 -std=c++23 -O1 -g -fsanitize=thread -Wall -Wextra -Wshadow
//       spsc-stress-test.cpp -o ../../../build/spsc-stress-test
// Run:
//   ../../../build/spsc-stress-test [items per configuration, default 1000000]

#include "../spsc.hpp"

#include <atomic>
#include <chrono>
#include <cstdint>
#include <cstdio>
#include <cstdlib>
#include <latch>
#include <thread>

extern "C" const char* __tsan_default_options(){
    return "halt_on_error=1";
}

namespace {

constexpr std::uint64_t K = 0x9E3779B97F4A7C15ULL;

// a and b are derived from seq, so a torn or stale slot read is caught even when seq looks right
struct Item{
    std::uint64_t seq;
    std::uint64_t a;
    std::uint64_t b;
};

Item make_item(std::uint64_t seq){
    return Item{seq, seq * K, ~seq};
}

struct Result{
    bool ok = true;
    std::uint64_t full_pushes = 0;    // push() returned false
    std::uint64_t empty_pops = 0;     // pop() returned nullopt
    std::uint64_t bad_index = 0;
    Item expected{}, got{};
};

template <std::size_t buckets>
bool run(std::uint64_t n){

    RingBuffer<Item, buckets> rb;

    // Progress and stop flags are relaxed: they must not add any ordering TSan would rely on
    std::atomic<std::uint64_t> consumed{0};
    std::atomic<bool> stop{false};
    std::latch start(2);
    Result prod, cons;

    const auto t0 = std::chrono::steady_clock::now();

    std::thread producer([&]{
        start.arrive_and_wait();
        for (std::uint64_t seq = 0; seq < n; ++seq){
            const Item item = make_item(seq);
            std::uint64_t spins = 0;
            while (!rb.push(item)){
                ++prod.full_pushes;
                if (stop.load(std::memory_order_relaxed))
                    return;
                if (++spins % 64 == 0)
                    std::this_thread::yield();
            }
        }
    });

    std::thread consumer([&]{
        start.arrive_and_wait();
        std::uint64_t spins = 0;
        for (std::uint64_t expected = 0; expected < n; ){
            auto item = rb.pop();
            if (!item){
                ++cons.empty_pops;
                if (stop.load(std::memory_order_relaxed))
                    return;
                if (++spins % 64 == 0)
                    std::this_thread::yield();
                continue;
            }
            const Item want = make_item(expected);
            if (item->seq != want.seq || item->a != want.a || item->b != want.b){
                cons.ok = false;
                cons.bad_index = expected;
                cons.expected = want;
                cons.got = *item;
                stop.store(true, std::memory_order_relaxed);
                return;
            }
            ++expected;
            consumed.store(expected, std::memory_order_relaxed);
        }
    });

    // Watchdog: no consumer progress for 10 s means an item was lost or a thread is stuck
    std::uint64_t last = 0;
    auto last_change = std::chrono::steady_clock::now();
    while (consumed.load(std::memory_order_relaxed) < n && !stop.load(std::memory_order_relaxed)){
        std::this_thread::sleep_for(std::chrono::milliseconds(50));
        const std::uint64_t now_consumed = consumed.load(std::memory_order_relaxed);
        if (now_consumed != last){
            last = now_consumed;
            last_change = std::chrono::steady_clock::now();
        } else if (std::chrono::steady_clock::now() - last_change > std::chrono::seconds(10)){
            std::printf("FAIL  buckets=%zu: no progress for 10 s, consumed %llu of %llu\n",
                        buckets, static_cast<unsigned long long>(now_consumed),
                        static_cast<unsigned long long>(n));
            std::fflush(stdout);
            std::abort();
        }
    }

    producer.join();
    consumer.join();

    const double ms = std::chrono::duration<double, std::milli>(std::chrono::steady_clock::now() - t0).count();

    if (!cons.ok){
        std::printf("FAIL  buckets=%zu: item %llu expected {seq %llu, a %llx, b %llx} got {seq %llu, a %llx, b %llx}\n",
                    buckets, static_cast<unsigned long long>(cons.bad_index),
                    static_cast<unsigned long long>(cons.expected.seq),
                    static_cast<unsigned long long>(cons.expected.a),
                    static_cast<unsigned long long>(cons.expected.b),
                    static_cast<unsigned long long>(cons.got.seq),
                    static_cast<unsigned long long>(cons.got.a),
                    static_cast<unsigned long long>(cons.got.b));
        return false;
    }

    std::printf("ok    buckets=%-5zu items %llu  full pushes %llu  empty pops %llu  %.0f ms\n",
                buckets, static_cast<unsigned long long>(n),
                static_cast<unsigned long long>(prod.full_pushes),
                static_cast<unsigned long long>(cons.empty_pops), ms);
    return true;
}

} // namespace

int main(int argc, char** argv){

    const std::uint64_t n = argc > 1 ? std::strtoull(argv[1], nullptr, 10) : 1'000'000;

    bool ok = true;
    ok = run<2>(n) && ok;       // capacity 1: every push and pop contends
    ok = run<4>(n) && ok;
    ok = run<64>(n) && ok;
    ok = run<1024>(n) && ok;

    std::printf("spsc stress (tsan): %s\n", ok ? "PASSED" : "FAILED");
    return ok ? EXIT_SUCCESS : EXIT_FAILURE;
}
